<?php
require __DIR__.'/bootstrap.php';
$code=strtoupper(trim($_GET['code']??$_POST['code']??''));$doc=null;$checked=false;
if($code!==''){$checked=true;$q=$pdo->prepare('SELECT d.verification_code,d.document_type,d.issued_at,d.revoked_at,m.name member_name,c.name church_name FROM issued_documents d INNER JOIN members m ON m.id=d.member_id INNER JOIN churches c ON c.id=d.church_id WHERE d.verification_code=? LIMIT 1');$q->execute([$code]);$doc=$q->fetch()?:null;}
$labels=['baptism_certificate'=>'Certificado de Batismo','membership_card'=>'Carteirinha de Membro','membership_certificate'=>'Certificado de Membro','recommendation_letter'=>'Carta de Recomendação','dismissal_letter'=>'Carta de Desligamento','visitor_presentation'=>'Carta de Apresentação','attendance_declaration'=>'Declaração de Frequência'];
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Verificação de Documentos</title><link rel="stylesheet" href="assets/app.css?v=1"><style>.verify-wrap{max-width:720px;margin:0 auto;padding:44px 16px}.verify-card{text-align:center}.verify-code{font-family:monospace;letter-spacing:1px}.valid{border-color:#86d19c;background:#f2fff6}.invalid{border-color:#ef9a9a;background:#fff5f5}</style></head><body><main class="verify-wrap"><section class="card card-pad verify-card"><h1>Verificação de Documentos</h1><p>Digite o código impresso no documento oficial.</p><form method="get" class="toolbar" style="justify-content:center"><input class="input verify-code" name="code" value="<?=e($code)?>" placeholder="Ex: BAP-ABC123-DEF456-..." required><button class="btn btn-primary">Verificar</button></form></section><?php if($checked):?><?php if($doc && !$doc['revoked_at']):?><section class="card card-pad verify-card valid"><h2>✅ Documento autêntico</h2><p>Este código existe no banco oficial do sistema.</p><p><strong>Documento:</strong> <?=e($labels[$doc['document_type']]??'Documento')?></p><p><strong>Membro:</strong> <?=e($doc['member_name'])?></p><p><strong>Igreja:</strong> <?=e($doc['church_name'])?></p><p><strong>Emitido em:</strong> <?=e(date('d/m/Y H:i',strtotime($doc['issued_at'])))?></p><p class="verify-code"><?=e($doc['verification_code'])?></p></section><?php else:?><section class="card card-pad verify-card invalid"><h2>❌ Documento inválido</h2><p><?=$doc&&$doc['revoked_at']?'Este documento foi revogado.':'O código informado não foi encontrado no banco oficial.'?></p></section><?php endif?><?php endif?></main></body></html>